import React from "react";
import ListNames from "../ListNames";
import ListCard from "../ListCard";




function createTeam(member) {
  return (
    <ListCard
      key={member.id}
      name={member.name}
      image={member.img}
      description={member.description}
    />
  );
}

function Team() {
  return (
    <div className="" >
      <h2 className="heading">Our Team</h2>
      {ListNames.map(createTeam)}
    </div>
  );
}

export default Team;
